import json, os, collections
root = r\"E:\\codex-LOOP\\codex-loop-s-f2\"
led_path = os.path.join(root, \"data\", \"progress_ledger.json\")
print(\"ledger exists:\", os.path.exists(led_path))
led = json.load(open(led_path, encoding=\"utf-8\")) if os.path.exists(led_path) else {}
pkts = led.get(\"packets\", {})
print(\"total ledger packets:\", len(pkts))
targets = {\"dispatch_refused\", \"spawn_health_gate_passed\", \"spawn_health_gate_failed\", \"spawn_initializing_timeout\"}
hits = collections.defaultdict(list)
with open(os.path.join(root, \"data\", \"events.ndjson\"), encoding=\"utf-8\") as f:
    for i, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        try:
            ev = json.loads(line)
        except Exception:
            continue
        if ev.get(\"event\") in targets:
            hits[ev[\"event\"]].append((i, ev.get(\"packet_id\")))
for name, rows in hits.items():
    print(name, \"count=\", len(rows))
    for i, pid in rows:
        pkt = pkts.get(pid)
        state = pkt.get(\"state\") if pkt else \"<not-in-ledger>\"
        # last history entry
        last = \"\"
        if pkt:
            h = pkt.get(\"history\") or []
            last = h[-1].get(\"via\") if h else \"(no history)\"
        print(f\"  line {i}: pid={pid} current_state={state} last_history_via={last}\")
# any packet dead-lettered with via containing health/refused?
for pid, pkt in pkts.items():
    for e in (pkt.get(\"history\") or []):
        via = str(e.get(\"via\", \"\"))
        if any(k in via for k in (\"health\", \"refused\", \"initializing_timeout\")):
            print(\"POLLUTION-SUSPECT:\", pid, pkt.get(\"state\"), via)
print(\"done\")
